//! Slint tutorial 05 (Rust) - an interface written in `.slint` files.
//!
//! `main.rs` now starts with `slint::include_modules!()`, which is generated by
//! `build.rs` from `ui/main.slint`. The UI is not a string in the binary
//! anymore: it is a file the compiler reads, with imports and components.
//!
//!   ui/main.slint              the window
//!   ui/components/header.slint a reusable header
//!   ui/components/status-bar.slint
//!
//! `MainWindow` is the exported component, with the same callbacks and
//! properties as before - moving a UI into files changes no Rust logic.

mod harness;

slint::include_modules!();

use std::cell::RefCell;
use std::rc::Rc;

struct Greeter {
    name: String,
}

impl Greeter {
    fn new() -> Self {
        Self {
            name: String::new(),
        }
    }

    fn greet(&self) -> String {
        let who = if self.name.trim().is_empty() {
            "world"
        } else {
            self.name.trim()
        };
        format!("Hello, {who}!")
    }
}

fn wire(ui: &MainWindow, greeter: &Rc<RefCell<Greeter>>) {
    let weak = ui.as_weak();
    let model = greeter.clone();
    ui.on_greet(move || {
        if let Some(ui) = weak.upgrade() {
            model.borrow_mut().name = ui.get_name().to_string();
            ui.set_greeting(model.borrow().greet().into());
            ui.set_status("Greeted".into());
        }
    });

    let weak = ui.as_weak();
    ui.on_quit_requested(move || {
        if let Some(ui) = weak.upgrade() {
            let _ = ui.hide();
        }
    });
}

fn main() {
    if harness::is_test() {
        let mut greeter = Greeter::new();
        harness::check(
            greeter.greet() == "Hello, world!",
            "an empty name greets the world",
        );
        greeter.name = String::from("Grace");
        harness::check(
            greeter.greet() == "Hello, Grace!",
            "the model uses the typed name",
        );
        greeter.name = String::from("  Ada  ");
        harness::check(
            greeter.greet() == "Hello, Ada!",
            "surrounding spaces are trimmed",
        );
        greeter.name.clear();
        harness::check(
            greeter.greet() == "Hello, world!",
            "clearing the name returns to world",
        );

        std::process::exit(harness::finish("05-slint-files"));
    }

    if let Err(error) = run() {
        eprintln!("05-slint-files: {error}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), slint::PlatformError> {
    let ui = MainWindow::new()?;
    let greeter = Rc::new(RefCell::new(Greeter::new()));
    wire(&ui, &greeter);
    ui.run()
}
